// Прод, только чтение: все объявления из sitemap, сырой HTML через request API, параллельно по 8.
import { test, expect } from '@playwright/test';
import { readSitemap, rawHtml, rootHtml, seoBody, h1s, labeled, jsonLd, listingNode, textOf, pool } from './ssr-seo.helpers';

test.describe('SSR и SEO публичных страниц — SSR-контент', () => {
  test('Объявления из sitemap: SSR-блок с h1 = название, «קטגוריה:»/«מיקום:» и описанием #b3dc2e @desktop @prod-safe', async ({ request }) => {
    test.setTimeout(10 * 60_000);
    const sm = await readSitemap(request);
    expect(sm.listingIds.length, 'объявления в sitemap').toBeGreaterThan(0);

    const rows = await pool(
      sm.listingIds,
      async (id) => {
        const problems: string[] = [];
        const { status, html } = await rawHtml(request, `/businessdetail?id=${id}`);
        if (status !== 200) return { id, problems: [`HTTP ${status}`], both: false };
        const seo = seoBody(rootHtml(html) ?? '');
        if (!seo) return { id, problems: ['нет [data-seo-body]'], both: false };
        if (seo.attr !== '/businessdetail') problems.push(`data-seo-body="${seo.attr}"`);

        const heads = h1s(seo.html);
        const node = listingNode(jsonLd(html));
        const name = String(node?.['name'] ?? '').trim();
        if (heads.length !== 1 || !heads[0]) problems.push(`h1: ${JSON.stringify(heads)}`);
        else if (name && heads[0] !== name.replace(/\s+/g, ' ')) problems.push(`h1 «${heads[0]}» ≠ name «${name}»`);

        // Метки — с непустым значением, если есть.
        for (const label of ['קטגוריה:', 'מיקום:', 'מחיר מבוקש:']) {
          const v = labeled(seo.html, label);
          if (v !== undefined && !v) problems.push(`«${label}» пустое`);
        }
        // Описание: абзац внутри <article>, если у объявления есть description.
        const article = seo.html.match(/<article\b[^>]*>([\s\S]*?)<\/article>/i)?.[1] ?? '';
        const paras = [...article.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi)].map((m) => textOf(m[1])).filter(Boolean);
        if (String(node?.['description'] ?? '').trim() && paras.length === 0) problems.push('нет абзаца описания');
        const both = !!labeled(seo.html, 'קטגוריה:') && !!labeled(seo.html, 'מיקום:');
        return { id, problems, both };
      },
      (id, e) => ({ id, problems: [`ошибка запроса: ${e.message.split('\n')[0]}`], both: false }),
    );

    const bad = rows.filter((r) => r.problems.length);
    expect(bad.map((r) => `${r.id}: ${r.problems.join('; ')}`), `нарушителей ${bad.length}/${rows.length}`).toEqual([]);

    // Хотя бы одно объявление с «קטגוריה:» и «מיקום:» — иначе метки не проверены.
    expect(rows.filter((r) => r.both).length, 'объявлений с «קטגוריה:» и «מיקום:»').toBeGreaterThan(0);
  });
});
